func redirecionar(w http.ResponseWriter, r *http.Request) {
	destino := r.URL.Query().Get("next")
	// só aceita caminho relativo interno (começa com / e não com //)
	if !strings.HasPrefix(destino, "/") || strings.HasPrefix(destino, "//") {
		destino = "/"
	}
	http.Redirect(w, r, destino, http.StatusFound)
}

