type Contador struct {
	mu      sync.Mutex
	valor   int
	fechado bool
}

func (c *Contador) Incrementar() error {
	c.mu.Lock()
	if c.fechado {
		return errors.New("fechado") // retorna com o mutex ainda travado
	}
	c.valor++
	c.mu.Unlock()
	return nil
}

