type Contador struct {
	mu      sync.Mutex
	valor   int
	fechado bool
}

func (c *Contador) Incrementar() error {
	c.mu.Lock()
	defer c.mu.Unlock() // Unlock garantido em todos os caminhos de retorno
	if c.fechado {
		return errors.New("fechado")
	}
	c.valor++
	return nil
}

